cd "D:\OpenCode"; @'
import os, re, glob
from html.parser import HTMLParser

files = ["index.html","services/index.html"] + sorted(glob.glob("services/*.html"))
files = sorted(set(files))

class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.ids=[]; self.refs=[]; self.stack=[]; self.errors=[]
        self.void={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.append(d['id'])
        for k in ('href','src'):
            if k in d and d[k] and not d[k].startswith(('#','http','mailto:','tel:','data:','javascript:')):
                self.refs.append(d[k])
        if tag not in self.void: self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void: return
        if self.stack and self.stack[-1]==tag:
            self.stack.pop()
        else:
            self.errors.append(f"unexpected </{tag}> (top={self.stack[-1] if self.stack else None})")
            if tag in self.stack:
                while self.stack and self.stack.pop()!=tag: pass

all_ids={}
for f in files:
    s=open(f,encoding='utf-8').read()
    p=P(); p.feed(s); p.close()
    dups={i for i in p.ids if p.ids.count(i)>1}
    missing=[]
    for r in p.refs:
        if r.startswith('#'): continue
        target=os.path.normpath(os.path.join(os.path.dirname(f), r.split('#')[0].split('?')[0]))
        if not os.path.exists(target): missing.append(r)
    print(f"{f}: ids={len(p.ids)} dup={sorted(dups)} unclosed={p.stack[-3:]} err={p.errors[:3]} missing={sorted(set(missing))}")
    all_ids[f]=set(p.ids)

print("\nTotal files:", len(files))
