const fs = require('fs'), path = require('path');
const files = ['index.html','services/index.html',...fs.readdirSync('services').filter(f=>f.endsWith('.html')&&f!=='index.html').map(f=>'services/'+f)];
let problems = [];
const idsBy = {};
for (const f of files) {
  const html = fs.readFileSync(f,'utf8');
  idsBy[f] = new Set([...html.matchAll(/\sid="([^"]+)"/g)].map(m=>m[1]));
  const ids = [...html.matchAll(/\sid="([^"]+)"/g)].map(m=>m[1]);
  const dup = ids.filter((v,i)=>ids.indexOf(v)!==i);
  if (dup.length) problems.push(`${f}: duplicate ids ${[...new Set(dup)]}`);
  const imgs = [...html.matchAll(/<img\b[^>]*>/g)].map(m=>m[0]);
  imgs.forEach(t=>{ if(!/\balt=/.test(t)) problems.push(`${f}: img missing alt: ${t.slice(0,80)}`); });
  const labels = [...html.matchAll(/<label\b[^>]*for="([^"]+)"/g)].map(m=>m[1]);
  labels.forEach(id=>{ if(!ids.includes(id)) problems.push(`${f}: label for missing #${id}`); });
  const aria = [...html.matchAll(/\baria-(?:labelledby|controls|describedby|owns)="([^"]+)"/g)].map(m=>m[1]);
  aria.forEach(v=>v.split(/\s+/).forEach(id=>{ if(id && !ids.includes(id)) problems.push(`${f}: aria ref missing #${id}`); }));
  const anchors = [...html.matchAll(/<a\b[^>]*href="([^"]*)"/g)].map(m=>m[1]);
  anchors.forEach(h=>{ if(!h||h.startsWith('http')||h.startsWith('tel:')||h.startsWith('mailto:')||h==='#') return; if(h.startsWith('#')){ if(!ids.includes(h.slice(1))) problems.push(`${f}: anchor missing ${h}`); return;} const clean=h.split('#')[0].split('?')[0]; const target=path.join(path.dirname(f),clean); if(!fs.existsSync(target)) problems.push(`${f}: missing link target ${h}`); });
  if (!/<html[^>]*lang="ar"/.test(html)) problems.push(`${f}: missing lang=ar`);
  if (!/<meta name="description"/.test(html)) problems.push(`${f}: missing meta description`);
  if ((html.match(/<h1\b/g)||[]).length!==1) problems.push(`${f}: h1 count ${(html.match(/<h1\b/g)||[]).length}`);
  const title = (html.match(/<title>([^<]*)<\/title>/)||[])[1]||'';
  if(title.length>70) problems.push(`${f}: title ${title.length} chars`);
}
console.log(problems.length? problems.join('\n') : 'OK: no structural problems in '+files.length+' files');
console.log('Files:', files.length);
