content.text:
Add focus trap JS. Current keydown handler handles Escape. Modify block:

```
document.addEventListener("keydown", function (event) {
  if (!menu.classList.contains("is-open")) return;
  if (event.key === "Escape") { closeMenu(); return; }
  if (event.key !== "Tab") return;
  var focusables = $$('a[href], button:not([disabled])', menu).filter(...)
  ...
});
```

Scope $$ accepts selector, scope. Need filter visible? menu open so visible. Use first/last. If activeElement outside menu, focus first.

Implement carefully.

input.newString:
document.addEventListener("keydown", function (event) {
  if (!menu.classList.contains("is-open")) return;

  if (event.key === "Escape") {
    closeMenu();
    return;
  }

  if (event.key !== "Tab") return;

  var focusable = $$("a[href], button:not([disabled])", menu);
  if (!focusable.length) return;

  var first = focusable[0];
  var last = focusable[focusable.length - 1];
  var active = document.activeElement;

  if (!menu.contains(active)) {
    event.preventDefault();
    first.focus();
  } else if (event.shiftKey && active === first) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && active === last) {
    event.preventDefault();
    first.focus();
  }
});

