const fs = require('fs'), path = require('path');
const files = ['index.html','services/index.html',...fs.readdirSync('services').filter(f=>f.endsWith('.html')&&f!=='index.html').map(f=>'services/'+f)];
let problems = [];
for (const f of files) {
  const html = fs.readFileSync(f,'utf8');
  const ids = [...html.matchAll(/\sid="([^"]+)"/g)].map(m=>m[1]);
  const dup = ids.filter((v,i)=>ids.indexOf(v)!==i);
  if (dup.length) problems.push(`${f}: duplicate ids ${[...new Set(dup)]}`);
  [...html.matchAll(/<img\b[^>]*>/g)].forEach(m=>{ if(!/\balt=/.test(m[0])) problems.push(`${f}: img missing alt`); });
  [...html.matchAll(/<label\b[^>]*for="([^"]+)"/g)].forEach(m=>{ if(!ids.includes(m[1])) problems.push(`${f}: label for missing #${m[1]}`); });
  [...html.matchAll(/\baria-(?:labelledby|controls|describedby|owns)="([^"]+)"/g)].forEach(m=>m[1].split(/\s+/).forEach(id=>{ if(id && !ids.includes(id)) problems.push(`${f}: aria ref missing #${id}`); }));
  [...html.matchAll(/<a\b[^>]*href="([^"]*)"/g)].forEach(m=>{const h=m[1]; if(!h||/^(https?:|tel:|mailto:)/.test(h)||h==='#') return; if(h.startsWith('#')){ if(!ids.includes(h.slice(1))) problems.push(`${f}: anchor missing ${h}`); return;} const clean=h.split('#')[0].split('?')[0]; if(!fs.existsSync(path.join(path.dirname(f),clean))) problems.push(`${f}: missing link target ${h}`);});
  if (!/<html[^>]*lang="ar"/.test(html)) problems.push(`${f}: missing lang=ar`);
  if (!/<meta name="description"/.test(html)) problems.push(`${f}: missing meta description`);
  const h1 = (html.match(/<h1\b/g)||[]).length; if(h1!==1) problems.push(`${f}: h1 count ${h1}`);
  const title=(html.match(/<title>([^<]*)<\/title>/)||[])[1]||''; if(title.length>70) problems.push(`${f}: title ${title.length} chars`);
  if(!/aria-label="[^"]*شركة خاطرخاطرك/.test(html) && /<a class="brand"[^>]*aria-label/.test(html)) problems.push(`${f}: brand aria-label still present`);
}
console.log(problems.length? problems.join('\n') : 'OK: '+files.length+' files pass structural audit');
