const fs = require('fs'), path = require('path');
const files = ['index.html','services/index.html',...fs.readdirSync('services').filter(f=>f.endsWith('.html')&&f!=='index.html').map(f=>'services/'+f)];
let problems = [];
for (const f of files) {
  const html = fs.readFileSync(f,'utf8');
  const ids = [...html.matchAll(/\sid="([^"]+)"/g)].map(m=>m[1]);
  if (new Set(ids).size !== ids.length) problems.push(`${f}: duplicate ids`);
  if ((html.match(/<img\b[^>]*>/g)||[]).some(t=>!/\balt=/.test(t))) problems.push(`${f}: img missing alt`);
  if ((html.match(/<h1\b/g)||[]).length!==1) problems.push(`${f}: h1 count`);
  const targets = [...html.matchAll(/<a\b[^>]*href="([^"]*)"/g)].map(m=>m[1]);
  for (const h of targets) {
    if (!h || /^(https?:|tel:|mailto:|#)/.test(h)) { if (h && h.startsWith('#') && !ids.includes(h.slice(1))) problems.push(`${f}: broken anchor ${h}`); continue; }
    const clean = h.split('#')[0].split('?')[0];
    if (!fs.existsSync(path.join(path.dirname(f), clean))) problems.push(`${f}: missing ${h}`);
  }
  const title = (html.match(/<title>([^<]*)<\/title>/)||[])[1]||'';
  if (title.length>70) problems.push(`${f}: long title`);
  if (!/lang="ar"/.test(html) || !/dir="rtl"/.test(html)) problems.push(`${f}: lang/dir`);
}
console.log(problems.length ? problems.join('\n') : `OK — ${files.length} pages, no structural problems`);
