const fs = require("fs");
const path = require("path");
const root = "D:/OpenCode";
const files = [];
function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (!["node_modules", ".git", "assets", "tools"].includes(e.name)) walk(p);
    } else if (e.name.endsWith(".html")) files.push(p);
  }
}
walk(root);
const css = fs.readFileSync(path.join(root, "assets/css/styles.css"), "utf8");
const cssClasses = new Set([...css.matchAll(/\.([a-zA-Z][\w-]*)/g)].map((m) => m[1]));
const used = new Map();
for (const f of files) {
  const html = fs.readFileSync(f, "utf8");
  for (const m of html.matchAll(/class="([^"]+)"/g)) {
    for (const c of m[1].split(/\s+/)) {
      if (!c) continue;
      if (!used.has(c)) used.set(c, new Set());
      used.get(c).add(path.relative(root, f));
    }
  }
}
const missing = [...used.keys()].filter((c) => !cssClasses.has(c)).sort();
console.log("FILES:", files.length);
console.log("MISSING CLASSES (" + missing.length + "):");
for (const c of missing) console.log(c + "  <- " + [...used.get(c)].slice(0, 3).join(", "));

