/* ==========================================================================
   Khatruk Travel & Tourism — rebrand layer
   Large bilingual brand, dropdown navigation, premium footer,
   smart travel tools and inner-page components.
   ========================================================================== */

/* ---------- Shared helpers ---------- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 3px solid rgba(201, 162, 75, 0.65);
  outline-offset: 3px;
}

/* ---------- Header shell ---------- */
.site-header {
  --hdr-fg: #fff;
  --hdr-muted: rgba(255, 255, 255, 0.66);
  color: var(--hdr-fg);
}

.site-header:not(.is-scrolled) {
  background: linear-gradient(180deg, rgba(16, 13, 40, 0.82) 0%, rgba(16, 13, 40, 0) 100%);
}

.site-header.is-scrolled {
  --hdr-fg: var(--ink);
  --hdr-muted: var(--muted);
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(20px) saturate(150%);
  box-shadow: 0 1px 0 var(--line), 0 22px 50px -40px rgba(27, 23, 64, 0.65);
}

.topbar {
  border-bottom-color: rgba(255, 255, 255, 0.12);
  background: rgba(12, 9, 32, 0.28);
  font-size: 0.76rem;
}

.topbar__inner {
  padding-block: 0.5rem;
  gap: 1.25rem;
}

.topbar__group {
  gap: 1rem;
}

.topbar__group--end {
  justify-content: flex-end;
}

.topbar__item {
  font-weight: 500;
  white-space: nowrap;
}

.topbar__item--phone {
  font-family: var(--font-body);
  font-size: 0.98rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  color: #fff;
}

.topbar__item--phone .ico {
  width: 15px;
  height: 15px;
}

.topbar__clock {
  font-variant-numeric: tabular-nums;
}

.topbar__notify {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  padding: 0.3rem 0.8rem;
  border: 1px solid rgba(201, 162, 75, 0.55);
  border-radius: 999px;
  background: rgba(201, 162, 75, 0.12);
  color: var(--gold-soft);
  font-family: var(--font-body);
  font-size: 0.72rem;
  font-weight: 700;
  cursor: pointer;
  transition: background-color 0.25s var(--ease-soft), color 0.25s var(--ease-soft),
    border-color 0.25s var(--ease-soft);
}

.topbar__notify .ico {
  width: 14px;
  height: 14px;
}

.topbar__notify:hover {
  background: var(--gold);
  border-color: var(--gold);
  color: #211a08;
}

.site-header.is-scrolled .topbar__item--phone {
  color: var(--deep);
}

/* ---------- Brand ---------- */
.brand {
  gap: 0.75rem;
}

.brand__mark {
  width: 56px;
  height: 56px;
  background: linear-gradient(145deg, #f0dca9, var(--gold) 48%, #96722c);
