const fs = require("fs");
const file = process.argv[2];
let html = fs.readFileSync(file, "utf8");
const main = html.slice(html.indexOf("<main"), html.indexOf("</main>"));
let out = main
  .replace(/<svg[\s\S]*?<\/svg>/g, "<svg/>")
  .replace(/<(\/?)([a-zA-Z0-9]+)([^>]*)>/g, (m, close, tag, attrs) => {
    if (/^(path|circle|rect|line|polyline|polygon)$/.test(tag)) return "";
    const cls = /class="([^"]*)"/.exec(attrs);
    const extra = [];
    for (const a of ["id", "data-tool", "data-tracking", "data-visa", "data-explore", "data-notify", "data-newsletter", "data-quote", "aria-live", "type", "name"]) {
      const r = new RegExp(a + '="([^"]*)"').exec(attrs);
      if (r) extra.push(a + "=" + r[1]);
    }
    if (close) return "";
    return "\n" + tag + (cls ? "." + cls[1].split(/\s+/).join(".") : "") + (extra.length ? " [" + extra.join(" ") + "]" : "");
  })
  .split("\n")
  .filter((l) => l.trim())
  .join("\n");
console.log(out);

