/* ==========================================================================
   Khatruk — homepage sections, travel tools & inner-page components
   ========================================================================== */

/* ---------- Single-column page layouts ---------- */
.page-hero__grid--single {
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
}

.page-grid--single {
  grid-template-columns: minmax(0, 1fr);
}

/* ---------- Homepage · smart travel tools ---------- */
.section--tools {
  background: #fff;
  border-block: 1px solid var(--line);
}

.tool-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.1rem;
}

.tool-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 1.5rem 1.35rem;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--sand);
  color: var(--text);
  transition: transform 0.4s var(--ease), box-shadow 0.4s var(--ease),
    border-color 0.4s var(--ease), background-color 0.4s var(--ease);
}

.tool-card:hover {
  transform: translateY(-5px);
  background: #fff;
  border-color: rgba(201, 162, 75, 0.5);
  box-shadow: var(--shadow-md);
}

.tool-card__icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin-bottom: 0.4rem;
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(201, 162, 75, 0.18), rgba(201, 162, 75, 0.06));
  border: 1px solid rgba(201, 162, 75, 0.3);
  color: var(--gold-deep);
  transition: background-color 0.3s var(--ease-soft), color 0.3s var(--ease-soft);
}

.tool-card:hover .tool-card__icon {
  background: var(--deep);
  border-color: var(--deep);
  color: var(--gold-soft);
}

.tool-card__icon .ico {
  width: 23px;
  height: 23px;
}

.tool-card__title {
  font-family: var(--font-display);
  font-size: 1.18rem;
  font-weight: 700;
  line-height: 1.4;
  color: var(--ink);
}

.tool-card__text {
  font-size: 0.82rem;
  line-height: 1.8;
  color: var(--muted);
}

.tool-card__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: auto;
  padding-top: 0.6rem;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--gold-deep);
}

.tool-card__cta .ico {
  width: 15px;
  height: 15px;
  transition: transform 0.3s var(--ease);
}

.tool-card:hover .tool-card__cta .ico {
  transform: translateX(-4px);
}

/* ---------- Homepage · corporate values ---------- */
.values-section {
  background: #fff;
  overflow: hidden;
}

.values-grid {
  display: grid;
  grid-template-columns: 350px minmax(0, 1fr);
  align-items: stretch;
  gap: clamp(1.5rem, 3vw, 2.5rem);
}

.values-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.1rem;
}

.value-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: clamp(1.4rem, 2vw, 1.9rem) clamp(1.15rem, 1.8vw, 1.6rem);
  border-radius: var(--radius-lg);
  border: 1px solid rgba(46, 39, 102, 0.08);
  background: #fff;
  box-shadow: 0 18px 45px -38px rgba(27, 23, 64, 0.55);
  transition: transform 0.4s var(--ease), box-shadow 0.4s var(--ease),
    border-color 0.4s var(--ease);
}

.value-card::before {
  content: "";
  position: absolute;
  inset-inline: 1.4rem;
  top: 0;
  height: 3px;
  border-radius: 0 0 4px 4px;
  background: linear-gradient(90deg, transparent, var(--gold), transparent);
  opacity: 0;
  transition: opacity 0.4s var(--ease-soft);
}

.value-card:hover {
  transform: translateY(-5px);
  border-color: rgba(201, 162, 75, 0.4);
  box-shadow: 0 32px 65px -42px rgba(27, 23, 64, 0.6);
}

.value-card:hover::before {
  opacity: 1;
}

.value-card__icon {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  margin-bottom: 0.9rem;
  border-radius: 18px;
  border: 1px solid rgba(201, 162, 75, 0.35);
  background: linear-gradient(150deg, rgba(201, 162, 75, 0.16), rgba(201, 162, 75, 0.03));
  color: var(--gold-deep);
}

.value-card__icon .ico {
  width: 28px;
  height: 28px;
  stroke-width: 1.4;
}

.value-card__title {
  font-family: var(--font-display);
  font-size: 1.22rem;
  font-weight: 700;
  line-height: 1.5;
  color: var(--ink);
}

.value-card__text {
  font-size: 0.83rem;
  line-height: 1.85;
  color: var(--muted);
}

.values-list {
  display: flex;
  flex-direction: column;
  padding: clamp(1.4rem, 2.4vw, 2rem);
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: var(--sand);
  box-shadow: 0 20px 50px -44px rgba(27, 23, 64, 0.55);
}

.values-list__title {
  font-family: var(--font-display);
  font-size: 1.22rem;
  font-weight: 700;
  line-height: 1.5;
  color: var(--ink);
}

.value-checks {
  display: grid;
  gap: 0.1rem;
  margin-top: 0.85rem;
}

.value-checks li {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  padding-block: 0.42rem;
  border-bottom: 1px dashed rgba(46, 39, 102, 0.12);
  font-size: 0.8rem;
  line-height: 1.7;
  color: var(--text);
}

.value-checks li:last-child {
  border-bottom: 0;
}

.value-checks .ico {
  width: 15px;
  height: 15px;
  margin-top: 0.32rem;
  flex: 0 0 auto;
  padding: 2px;
  border-radius: 50%;
  background: rgba(47, 111, 237, 0.12);
  color: var(--blue-check);
  stroke-width: 3;
}

.values-list .btn {
  width: 100%;
  margin-top: auto;
  padding-top: 0.85rem;
}

.values-list .btn {
  margin-top: 1.1rem;
}

/* ---------- Homepage · VIP band ---------- */
.vip-band {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  align-items: center;
  gap: clamp(1.75rem, 4vw, 3.5rem);
  padding: clamp(2rem, 4.5vw, 3.6rem);
  border-radius: var(--radius-xl);
  background:
    radial-gradient(70% 90% at 100% 0%, rgba(201, 162, 75, 0.22), transparent 62%),
    radial-gradient(60% 80% at 0% 100%, rgba(59, 52, 121, 0.85), transparent 70%),
    linear-gradient(135deg, #241f52, #14112f);
  color: #fff;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.vip-band::after {
  content: "";
  position: absolute;
  inset-inline-end: -80px;
  top: -90px;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  border: 1px solid rgba(201, 162, 75, 0.22);
  pointer-events: none;
}

.vip-band__copy {
  position: relative;
  z-index: 1;
  display: grid;
  justify-items: start;
  gap: 0.7rem;
}

.vip-band__copy .display {
  color: #fff;
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  line-height: 1.3;
}

.vip-band__copy .lede {
  color: rgba(255, 255, 255, 0.68);
  max-width: 52ch;
}

.vip-band__copy .btn-group {
  margin-top: 0.9rem;
}

.vip-band__side {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 0.65rem;
}

.vip-stat {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0.85rem 1rem;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(8px);
}

.vip-stat__icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  border-radius: 12px;
  background: rgba(201, 162, 75, 0.16);
  color: var(--gold-soft);
}

.vip-stat__icon .ico {
  width: 20px;
  height: 20px;
}

.vip-stat strong {
  display: block;
  font-size: 0.88rem;
  line-height: 1.5;
  color: #fff;
}

.vip-stat small {
  display: block;
  font-size: 0.7rem;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.5);
}

/* ---------- Homepage · transport coverage ---------- */
.country-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.1rem;
}

.country-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  padding: 1.6rem 1.35rem;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: #fff;
  color: var(--text);
  transition: transform 0.4s var(--ease), box-shadow 0.4s var(--ease),
    border-color 0.4s var(--ease);
}

.country-card:hover {
  transform: translateY(-5px);
  border-color: rgba(201, 162, 75, 0.5);
  box-shadow: var(--shadow-md);
}

.country-card__icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  margin-bottom: 0.5rem;
  border-radius: 13px;
  background: rgba(46, 39, 102, 0.06);
  color: var(--deep);
}

.country-card__icon .ico {
  width: 22px;
  height: 22px;
}

.country-card__name {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  line-height: 1.4;
  color: var(--ink);
}

.country-card__places {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--gold-deep);
}

.country-card p {
  font-size: 0.81rem;
  line-height: 1.85;
  color: var(--muted);
}

.country-card__link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: auto;
  padding-top: 0.8rem;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--deep);
}

.country-card__link .ico {
  width: 15px;
  height: 15px;
  transition: transform 0.3s var(--ease);
}

.country-card__link:hover {
  color: var(--gold-deep);
}

.country-card__link:hover .ico {
  transform: translateX(-4px);
}

.country-card--mini {
  padding: 1.15rem;
  gap: 0.3rem;
  background: var(--sand);
}

.country-card--mini .country-card__name {
  font-size: 1.1rem;
}

.country-card--mini p {
  font-size: 0.77rem;
}

/* ---------- Homepage · promo cards ---------- */
.promo-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.25rem;
}

.promo {
  position: relative;
  display: grid;
  justify-items: start;
  align-content: start;
  gap: 0.7rem;
  padding: clamp(1.8rem, 3.5vw, 2.8rem);
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.promo__icon {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  border-radius: 14px;
  border: 1px solid rgba(201, 162, 75, 0.35);
  background: rgba(201, 162, 75, 0.12);
  color: var(--gold-soft);
}

.promo__icon .ico {
  width: 24px;
  height: 24px;
}

.promo .display {
  font-size: clamp(1.55rem, 2.4vw, 2.15rem);
  line-height: 1.35;
}

.promo .lede {
  font-size: 0.9rem;
  line-height: 1.9;
}

.promo .btn-group {
  margin-top: 0.7rem;
}

.promo--quote {
  background:
    radial-gradient(70% 80% at 100% 0%, rgba(201, 162, 75, 0.2), transparent 60%),
    linear-gradient(135deg, #2e2766, #171334);
  color: #fff;
}

.promo--quote .display {
  color: #fff;
}

.promo--quote .lede {
  color: rgba(255, 255, 255, 0.68);
}

.promo--notify {
  border: 1px solid var(--line);
  background: #fff;
  box-shadow: 0 24px 60px -50px rgba(27, 23, 64, 0.6);
}

.promo--notify .promo__icon {
  border-color: rgba(46, 39, 102, 0.14);
  background: rgba(46, 39, 102, 0.06);
  color: var(--deep);
}

.promo--notify .display {
  color: var(--ink);
}

.promo--notify .lede {
  color: var(--muted);
}

.promo--notify .newsletter {
  margin-top: 0.6rem;
}

.promo__note {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.72rem;
  color: rgba(255, 255, 255, 0.5);
}

.promo--notify .promo__note {
  color: var(--muted);
}

/* ---------- Footer newsletter copy ---------- */
.footer-news__copy {
  display: grid;
  gap: 0.15rem;
}

/* ---------- Branches ---------- */
.branch-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.1rem;
  margin-top: 1.3rem;
}

.branch-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  padding: 1.6rem 1.4rem;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--sand);
}

.branch-card--main {
  border-color: rgba(201, 162, 75, 0.42);
  background: linear-gradient(160deg, #fff, #fbf6ea);
}

.branch-card__badge {
  position: absolute;
  top: 1.15rem;
  inset-inline-end: 1.15rem;
  padding: 0.2rem 0.65rem;
  border-radius: 999px;
  background: var(--deep);
  color: var(--gold-soft);
  font-size: 0.65rem;
  font-weight: 700;
}

.branch-card__icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  margin-bottom: 0.35rem;
  border-radius: 13px;
  background: rgba(46, 39, 102, 0.07);
  color: var(--deep);
}

.branch-card__icon .ico {
  width: 22px;
  height: 22px;
}

.branch-card h3 {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.5;
  color: var(--ink);
}

.branch-card__address {
  font-size: 0.82rem;
  line-height: 1.85;
  color: var(--muted);
}

.branch-card__address small {
  font-size: 0.72rem;
  color: var(--gold-deep);
}

.branch-card__rows {
  display: grid;
  gap: 0.35rem;
  margin-top: 0.5rem;
  padding-top: 0.7rem;
  border-top: 1px dashed var(--line-strong);
}

.branch-card__rows > * {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.78rem;
  color: var(--text);
  word-break: break-word;
}

.branch-card__rows .ico {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
  color: var(--gold-deep);
}

.branch-card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.85rem;
}

/* ---------- Destinations ---------- */
.dest-block {
  margin-top: 1.2rem;
  padding: 1.2rem;
  border-radius: 18px;
  border: 1px solid var(--line);
  background: var(--sand);
}

.dest-block__head {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px dashed var(--line-strong);
}

.dest-block__flag {
  font-size: 1.7rem;
  line-height: 1;
}

.dest-block__head strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.1rem;
  color: var(--ink);
  line-height: 1.4;
}

.dest-block__head span {
  display: block;
  font-size: 0.72rem;
  color: var(--muted);
}

.dest-cities {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.85rem;
}

.dest-cities span {
  padding: 0.25rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: #fff;
  font-size: 0.73rem;
  color: var(--text);
}

.dest-cities--large span {
  border-color: rgba(201, 162, 75, 0.35);
  background: rgba(201, 162, 75, 0.08);
  color: var(--gold-deep);
  font-weight: 700;
}

.dest-block__services {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.1rem;
  margin-top: 1rem;
  padding-top: 0.85rem;
  border-top: 1px dashed var(--line-strong);
}

.dest-block__services a {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--deep);
}

.dest-block__services a:hover {
  color: var(--gold-deep);
}

.dest-block__services .ico {
  width: 14px;
  height: 14px;
  color: var(--gold-deep);
}

/* ---------- Partners ---------- */
.partner-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1.3rem;
}

.partner-card {
  padding: 1.25rem;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: var(--sand);
  transition: transform 0.35s var(--ease), box-shadow 0.35s var(--ease),
    border-color 0.35s var(--ease);
}

.partner-card:hover {
  transform: translateY(-4px);
  border-color: rgba(201, 162, 75, 0.4);
  box-shadow: var(--shadow-sm);
}

.partner-card > span {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-bottom: 0.7rem;
  border-radius: 12px;
  background: rgba(46, 39, 102, 0.06);
  color: var(--deep);
}

.partner-card svg {
  width: 20px;
  height: 20px;
}

.partner-card h3 {
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.partner-card p {
  margin-top: 0.2rem;
  font-size: 0.76rem;
  line-height: 1.8;
  color: var(--muted);
}

/* ---------- Vision & mission cards ---------- */
.mission-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.9rem;
  margin-top: 1.3rem;
}

.mission-card {
  padding: 1.2rem;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: var(--sand);
}

.mission-card > span {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-bottom: 0.7rem;
  border-radius: 12px;
  background: rgba(201, 162, 75, 0.12);
  color: var(--gold-deep);
}

.mission-card svg {
  width: 20px;
  height: 20px;
}

.mission-card h3 {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.mission-card p {
  margin-top: 0.15rem;
  font-size: 0.76rem;
  line-height: 1.8;
  color: var(--muted);
}

/* ---------- Payment methods ---------- */
.method-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1.3rem;
}

.method-card {
  padding: 1.25rem;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: var(--sand);
}

.method-card > span {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-bottom: 0.7rem;
  border-radius: 12px;
  background: rgba(46, 39, 102, 0.06);
  color: var(--deep);
}

.method-card svg {
  width: 20px;
  height: 20px;
}

.method-card h3 {
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.method-card p {
  margin-top: 0.2rem;
  font-size: 0.76rem;
  line-height: 1.8;
  color: var(--muted);
}

/* ---------- Manager message ---------- */
.manager-sign {
  display: grid;
  gap: 0.15rem;
  margin-top: 1.6rem;
  padding-top: 1.2rem;
  border-top: 1px solid var(--line);
  justify-items: start;
}

.manager-sign__line {
  width: 64px;
  height: 2px;
  margin-bottom: 0.55rem;
  border-radius: 2px;
  background: var(--gold);
}

.manager-sign strong {
  font-family: var(--font-display);
  font-size: 1.05rem;
  color: var(--ink);
}

.manager-sign > span:last-child {
  font-family: var(--font-latin);
  font-size: 1rem;
  letter-spacing: 0.04em;
  color: var(--gold-deep);
}

/* ---------- Mini country grid ---------- */
.mini-country-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.8rem;
  margin-top: 1.2rem;
}

.mini-country {
  display: grid;
  gap: 0.15rem;
  padding: 1rem 1.1rem;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: var(--sand);
}

.mini-country strong {
  font-family: var(--font-display);
  font-size: 1.02rem;
  color: var(--ink);
}

.mini-country span {
  font-size: 0.73rem;
  line-height: 1.7;
  color: var(--muted);
}

/* ---------- Contact page ---------- */
.contact-page-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  align-items: start;
  gap: clamp(1.5rem, 3.5vw, 2.75rem);
}

.contact-page-side {
  display: grid;
  gap: 1rem;
}

.contact-block {
  padding: 1.4rem;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: #fff;
  box-shadow: 0 18px 45px -42px rgba(27, 23, 64, 0.55);
}

.contact-block__icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  margin-bottom: 0.7rem;
  border-radius: 13px;
  background: rgba(201, 162, 75, 0.12);
  color: var(--gold-deep);
}

.contact-block__icon .ico {
  width: 21px;
  height: 21px;
}

.contact-block h2 {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.contact-block p {
  margin-top: 0.35rem;
  font-size: 0.82rem;
  line-height: 1.85;
  color: var(--muted);
}

.contact-block p strong {
  color: var(--text);
}

.contact-block__en {
  font-size: 0.72rem !important;
  line-height: 1.7 !important;
  color: var(--muted) !important;
  direction: ltr;
  text-align: start;
}

.contact-block .btn {
  margin-top: 0.8rem;
}

.contact-block__link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.6rem;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--deep);
}

.contact-block__link .ico {
  width: 14px;
  height: 14px;
  color: var(--gold-deep);
}

.contact-block__handle {
  display: block;
  margin-top: 0.6rem;
  font-family: var(--font-latin);
  font-size: 1rem;
  letter-spacing: 0.05em;
  color: var(--gold-deep);
}

.footer-social__links--dark {
  margin-top: 0.55rem;
}

.footer-social__links--dark .social-link {
  border-color: var(--line-strong);
  color: var(--deep);
}

.footer-social__links--dark .social-link:hover {
  border-color: var(--gold);
  background: rgba(201, 162, 75, 0.12);
  color: var(--gold-deep);
}

/* ---------- Quote page ---------- */
.quote-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  align-items: start;
  gap: clamp(1.5rem, 3.5vw, 2.75rem);
}

.quote-side {
  display: grid;
  gap: 1rem;
}

.quote-promise {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1.4rem;
}

.quote-promise > span {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.3rem 0.8rem;
  border-radius: 999px;
  border: 1px solid rgba(201, 162, 75, 0.4);
  background: rgba(201, 162, 75, 0.1);
  font-size: 0.73rem;
  font-weight: 700;
  color: var(--gold-soft);
}

.quote-promise .ico {
  width: 14px;
  height: 14px;
}

.form-card--page {
  padding: clamp(1.5rem, 3vw, 2.4rem);
  border-color: var(--line);
  box-shadow: 0 30px 70px -60px rgba(27, 23, 64, 0.6);
}

.checklist--sm li {
  padding-block: 0.5rem;
  font-size: 0.79rem;
}

.checklist--sm .ico {
  width: 15px;
  height: 15px;
}

/* ---------- Shared tool layout ---------- */
.tool-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  align-items: start;
  gap: clamp(1.5rem, 3.5vw, 2.5rem);
}

.tool-panel {
  padding: clamp(1.4rem, 3vw, 2.2rem);
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: #fff;
  box-shadow: 0 28px 65px -58px rgba(27, 23, 64, 0.6);
}

.tool-panel--wide {
  max-width: 100%;
}

.tool-panel__head {
  margin-bottom: 1.3rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--line);
}

.tool-panel__head h2 {
  font-family: var(--font-display);
  font-size: clamp(1.3rem, 2vw, 1.65rem);
  font-weight: 700;
  color: var(--ink);
  line-height: 1.45;
}

.tool-panel__head p {
  margin-top: 0.25rem;
  font-size: 0.82rem;
  color: var(--muted);
}

.tool-form .form-grid {
  margin-top: 0.2rem;
}

.tool-form--inline {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 0.9rem;
}

.tool-form--inline .btn {
  margin-bottom: 0.05rem;
}

.tool-result {
  margin-top: 1.25rem;
}

.tool-result:empty {
  display: none;
}

.tool-side {
  display: grid;
  gap: 1rem;
}

.tool-side__card {
  padding: 1.35rem;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: #fff;
}

.tool-side__card h2 {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.tool-side__card p {
  margin-top: 0.3rem;
  margin-bottom: 0.85rem;
  font-size: 0.8rem;
  line-height: 1.8;
  color: var(--muted);
}

.tool-side__card--dark {
  border-color: rgba(201, 162, 75, 0.3);
  background:
    radial-gradient(80% 80% at 100% 0%, rgba(201, 162, 75, 0.18), transparent 60%),
    linear-gradient(140deg, #2e2766, #1b1740);
  color: #fff;
}

.tool-side__card--dark h2 {
  color: #fff;
}

.tool-side__card--dark p {
  color: rgba(255, 255, 255, 0.65);
}

.tool-side__card--dark .btn-ghost {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.35);
}

.tool-side__card .btn--block + .btn--block {
  margin-top: 0.5rem;
}

.tool-side__card .aside-phone {
  margin-top: 0.8rem;
  color: rgba(255, 255, 255, 0.8);
}

/* ---------- Status legend ---------- */
.legend-list {
  display: grid;
  gap: 0.55rem;
}

.legend-list li {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  font-size: 0.78rem;
  line-height: 1.7;
  color: var(--text);
}

.legend-list strong {
  font-weight: 700;
}

.legend-list--status {
  gap: 0.65rem;
}

.status-dot {
  width: 10px;
  height: 10px;
  flex: 0 0 auto;
  margin-top: 0.45rem;
  border-radius: 50%;
  background: var(--muted);
  box-shadow: 0 0 0 4px rgba(108, 106, 136, 0.14);
}

.status-dot--received,
.status-dot--evisa {
  background: var(--blue-check);
  box-shadow: 0 0 0 4px rgba(47, 111, 237, 0.14);
}

.status-dot--progress,
.status-dot--arrival {
  background: var(--gold-deep);
  box-shadow: 0 0 0 4px rgba(201, 162, 75, 0.18);
}

.status-dot--action,
.status-dot--required {
  background: #d4772a;
  box-shadow: 0 0 0 4px rgba(212, 119, 42, 0.16);
}

.status-dot--done,
.status-dot--free {
  background: #1f9d6b;
  box-shadow: 0 0 0 4px rgba(31, 157, 107, 0.16);
}

/* ---------- Tracking note & hints ---------- */
.tracking-note {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  padding: 0.8rem 0.95rem;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: var(--sand);
  font-size: 0.75rem;
  line-height: 1.7;
  color: var(--muted);
}

.tracking-note .ico {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
  margin-top: 0.2rem;
  color: var(--gold-deep);
}

.field__hint {
  font-size: 0.68rem;
  line-height: 1.6;
  color: var(--muted);
}

.tool-info {
  padding-block: clamp(2.75rem, 5vw, 4rem);
}

/* ---------- Tool results ---------- */
.result-card {
  padding: clamp(1.15rem, 2.4vw, 1.6rem);
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--sand);
}

.result-card + .result-card {
  margin-top: 0.85rem;
}

.result-card--accent {
  border-color: rgba(201, 162, 75, 0.45);
  background: linear-gradient(160deg, #fff, #fbf6ea);
}

.result-card--ok {
  border-color: rgba(31, 157, 107, 0.4);
  background: linear-gradient(160deg, #fff, #f1fbf6);
}

.result-card--warn {
  border-color: rgba(212, 119, 42, 0.4);
  background: linear-gradient(160deg, #fff, #fdf5ec);
}

.result-card__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem;
  padding-bottom: 0.75rem;
  margin-bottom: 0.85rem;
  border-bottom: 1px solid var(--line);
}

.result-card__head h3 {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.result-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.2rem 0.65rem;
  border-radius: 999px;
  background: rgba(46, 39, 102, 0.08);
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--deep);
}

.result-badge--gold {
  background: rgba(201, 162, 75, 0.16);
  color: var(--gold-deep);
}

.result-badge--ok {
  background: rgba(31, 157, 107, 0.14);
  color: #177a52;
}

.result-badge--warn {
  background: rgba(212, 119, 42, 0.14);
  color: #a85a19;
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem 1.25rem;
}

.result-item {
  display: grid;
  gap: 0.05rem;
  padding-block: 0.35rem;
  border-bottom: 1px dashed rgba(46, 39, 102, 0.12);
}

.result-item__label {
  font-size: 0.68rem;
  color: var(--muted);
  line-height: 1.5;
}

.result-item__value {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.6;
}

.result-note {
  margin-top: 0.8rem;
  font-size: 0.75rem;
  line-height: 1.75;
  color: var(--muted);
}

.result-note .ico {
  width: 14px;
  height: 14px;
  display: inline-block;
  vertical-align: -2px;
  color: var(--gold-deep);
}

.result-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1rem;
}

.result-list {
  display: grid;
  gap: 0.4rem;
  margin-top: 0.6rem;
}

.result-list li {
  position: relative;
  padding-inline-start: 1.1rem;
  font-size: 0.79rem;
  line-height: 1.75;
  color: var(--text);
}

.result-list li::before {
  content: "";
  position: absolute;
  inset-inline-start: 0;
  top: 0.6rem;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--gold);
}

.result-title {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
  margin-top: 1rem;
}

.result-sub {
  font-size: 0.75rem;
  color: var(--muted);
  line-height: 1.6;
}

/* ---------- Discover countries ---------- */
.explore-summary {
  margin-top: 1rem;
  padding: 0.85rem 1rem;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: var(--sand);
  font-size: 0.82rem;
  line-height: 1.8;
  color: var(--text);
}

.explore-summary strong {
  color: var(--deep);
}

.country-result-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem;
  margin-top: 1rem;
}

.country-result-grid:empty {
  display: none;
}

.info-cards {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
}

.info-card {
  padding: 1.25rem;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: #fff;
  box-shadow: 0 16px 40px -38px rgba(27, 23, 64, 0.5);
}

.info-card > span {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-bottom: 0.7rem;
  border-radius: 12px;
  background: rgba(46, 39, 102, 0.06);
  color: var(--deep);
}

.info-card svg {
  width: 20px;
  height: 20px;
}

.info-card h3 {
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.info-card p {
  margin-top: 0.2rem;
  font-size: 0.76rem;
  line-height: 1.8;
  color: var(--muted);
}

/* ---------- Notifications page ---------- */
.notify-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  align-items: start;
  gap: clamp(1.5rem, 3vw, 2.5rem);
}

.notify-panel {
  position: relative;
  padding: clamp(1.6rem, 3vw, 2.4rem);
  border-radius: var(--radius-lg);
  background:
    radial-gradient(75% 80% at 100% 0%, rgba(201, 162, 75, 0.2), transparent 62%),
    linear-gradient(140deg, #2e2766, #171334);
  color: #fff;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.notify-panel__icon {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  margin-bottom: 1rem;
  border-radius: 18px;
  border: 1px solid rgba(201, 162, 75, 0.4);
  background: rgba(201, 162, 75, 0.14);
  color: var(--gold-soft);
}

.notify-panel__icon .ico {
  width: 28px;
  height: 28px;
}

.notify-panel h2 {
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 2.4vw, 1.9rem);
  font-weight: 700;
  line-height: 1.4;
  color: #fff;
}

.notify-panel > p {
  margin-top: 0.4rem;
  max-width: 48ch;
  font-size: 0.85rem;
  line-height: 1.85;
  color: rgba(255, 255, 255, 0.66);
}

.notify-panel .btn {
  margin-top: 1.1rem;
}

.notify-panel__status {
  margin-top: 0.75rem;
  font-size: 0.76rem;
  line-height: 1.7;
  color: var(--gold-soft);
}

.notify-points {
  display: grid;
  gap: 0.5rem;
  margin-top: 1.3rem;
  padding-top: 1.1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}

.notify-points li {
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
  font-size: 0.79rem;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.72);
}

.notify-points .ico {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
  margin-top: 0.25rem;
  color: var(--gold);
}

.notify-prefs {
  padding: clamp(1.4rem, 2.6vw, 2rem);
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: #fff;
  box-shadow: 0 26px 60px -58px rgba(27, 23, 64, 0.6);
}

.notify-prefs h2 {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.prefs-form {
  display: grid;
  gap: 0.55rem;
  margin-top: 1rem;
}

.pref {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.65rem 0.8rem;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: var(--sand);
  cursor: pointer;
  transition: border-color 0.25s var(--ease-soft), background-color 0.25s var(--ease-soft);
}

.pref:hover {
  border-color: rgba(201, 162, 75, 0.45);
  background: #fff;
}

.pref input {
  width: 17px;
  height: 17px;
  accent-color: var(--gold-deep);
  flex: 0 0 auto;
}

.pref span {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text);
}

.pref .ico {
  width: 16px;
  height: 16px;
  color: var(--gold-deep);
}

.prefs-form .btn {
  margin-top: 0.5rem;
}

.notify-prefs__note {
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
  margin-top: 0.75rem;
  font-size: 0.7rem;
  line-height: 1.7;
  color: var(--muted);
}

.notify-prefs__note .ico {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  margin-top: 0.2rem;
  color: var(--gold-deep);
}

.notify-fallback {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: center;
  gap: 1.25rem;
  margin-top: 1.25rem;
  padding: clamp(1.3rem, 2.6vw, 1.9rem);
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: var(--sand);
}

.notify-fallback h2 {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.5;
}

.notify-fallback p {
  margin-top: 0.2rem;
  font-size: 0.8rem;
  line-height: 1.75;
  color: var(--muted);
}

/* ---------- Legal tables ---------- */
.legal-table-wrap {
  margin-top: 1.1rem;
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow-x: auto;
  background: #fff;
}

.legal-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 460px;
  font-size: 0.81rem;
  text-align: start;
}

.legal-table th {
  padding: 0.75rem 1rem;
  background: var(--sand);
  border-bottom: 1px solid var(--line-strong);
  font-family: var(--font-display);
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--ink);
  text-align: start;
  white-space: nowrap;
}

.legal-table td {
  padding: 0.7rem 1rem;
  border-bottom: 1px solid var(--line);
  line-height: 1.7;
  color: var(--text);
  vertical-align: top;
}

.legal-table tbody tr:last-child td {
  border-bottom: 0;
}

.legal-table tbody tr:nth-child(even) {
  background: rgba(246, 247, 252, 0.7);
}

/* ---------- Reviews form ---------- */
.review-form {
  margin-top: 1rem;
}

.review-form .form-grid {
  margin-top: 0.2rem;
}

/* ---------- Small shared lists ---------- */
.steps-list--compact {
  margin-top: 1rem;
  gap: 0.75rem;
}

.steps-list--compact li {
  padding-bottom: 0.75rem;
}

.steps-list--compact .steps-list__num {
  width: 30px;
  height: 30px;
  font-size: 0.75rem;
}

.steps-list--compact .steps-list__title {
  font-size: 0.92rem;
}

.steps-list--compact .steps-list__text {
  font-size: 0.77rem;
}

.note-box--wide {
  margin-top: 1.5rem;
  align-items: flex-start;
}

/* ---------- Cookie note ---------- */
.cookie-note {
  position: fixed;
  inset-inline: 1rem;
  bottom: 1rem;
  z-index: 120;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 1rem;
  max-width: 860px;
  margin-inline: auto;
  padding: 1rem 1.2rem;
  border-radius: 18px;
  border: 1px solid rgba(201, 162, 75, 0.35);
  background: rgba(23, 19, 52, 0.97);
  color: rgba(255, 255, 255, 0.74);
  box-shadow: 0 30px 70px -30px rgba(10, 8, 30, 0.8);
  backdrop-filter: blur(14px);
}

.cookie-note p {
  font-size: 0.76rem;
  line-height: 1.8;
}

.cookie-note p a {
  color: var(--gold-soft);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.cookie-note p .ico {
  display: inline-block;
  width: 15px;
  height: 15px;
  vertical-align: -3px;
  margin-inline-end: 0.2rem;
  color: var(--gold);
}

.cookie-note__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.cookie-note .btn-outline {
  border-color: rgba(255, 255, 255, 0.3);
  color: #fff;
}

.cookie-note.is-hidden {
  opacity: 0;
  visibility: hidden;
  transform: translateY(16px);
  transition: opacity 0.3s var(--ease-soft), transform 0.3s var(--ease-soft),
    visibility 0s linear 0.3s;
}

/* ---------- Toasts ---------- */
.toast-region {
  position: fixed;
  inset-inline-start: 1rem;
  bottom: 1rem;
  z-index: 200;
  display: grid;
  gap: 0.5rem;
  width: min(360px, calc(100vw - 2rem));
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  padding: 0.8rem 1rem;
  border-radius: 14px;
  border: 1px solid rgba(201, 162, 75, 0.35);
  background: rgba(23, 19, 52, 0.97);
  color: rgba(255, 255, 255, 0.82);
  box-shadow: 0 24px 50px -28px rgba(10, 8, 30, 0.85);
  font-size: 0.79rem;
  line-height: 1.7;
  pointer-events: auto;
  animation: toastIn 0.4s var(--ease) both;
}

.toast .ico {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  margin-top: 0.2rem;
  color: var(--gold);
}

.toast--ok {
  border-color: rgba(31, 157, 107, 0.45);
}

.toast--ok .ico {
  color: #57d6a4;
}

.toast--warn {
  border-color: rgba(212, 119, 42, 0.5);
}

.toast--warn .ico {
  color: #f0a468;
}

.toast.is-out {
  animation: toastOut 0.3s var(--ease-soft) forwards;
}

@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes toastOut {
  to {
    opacity: 0;
    transform: translateY(10px);
  }
}

/* ==========================================================================
   Responsive
   ========================================================================== */

@media (max-width: 1240px) {
  .brand--lg .brand__name {
    font-size: 1.4rem;
  }

  .nav__list {
    gap: 0.9rem;
  }

  .header-phone {
    display: none;
  }
}

@media (max-width: 1100px) {
  :root {
    --header-h: 82px;
  }

  .nav {
    display: none;
  }

  .nav-toggle {
    display: grid;
  }

  .site-header.is-scrolled .header-bar__inner {
    height: 68px;
  }

  .tool-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .values-grid {
    grid-template-columns: 300px minmax(0, 1fr);
  }

  .country-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .info-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1024px) {
  .values-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .values-list {
    order: -1;
  }

  .values-cards {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .vip-band {
    grid-template-columns: minmax(0, 1fr);
  }

  .vip-band__side {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .vip-stat {
    align-items: flex-start;
  }

  .promo-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .quote-layout,
  .tool-layout,
  .contact-page-grid,
  .notify-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .tool-side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .quote-side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .quote-side > .aside-card:first-child {
    grid-column: 1 / -1;
  }

  .contact-page-side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .contact-page-side > .contact-block:first-child {
    grid-column: 1 / -1;
  }

  .country-result-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .footer-news__inner {
    grid-template-columns: minmax(0, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1.75rem;
  }

  .footer-grid .footer-col:first-child {
    grid-column: 1 / -1;
  }

  .branch-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .partner-grid,
  .method-grid,
  .mission-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .notify-fallback {
    grid-template-columns: minmax(0, 1fr);
  }

  .values-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .vip-band__side {
    grid-template-columns: minmax(0, 1fr);
  }

  .vip-stat {
    align-items: center;
  }

  .header-actions .btn {
    display: none;
  }

  .result-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .cookie-note {
    grid-template-columns: minmax(0, 1fr);
  }

  .cookie-note__actions .btn {
    flex: 1 1 auto;
  }
}

@media (max-width: 720px) {
  .topbar {
    display: none;
  }

  .tool-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .values-cards {
    grid-template-columns: minmax(0, 1fr);
  }

  .value-card__icon {
    width: 50px;
    height: 50px;
  }

  .country-grid,
  .country-result-grid,
  .info-cards,
  .partner-grid,
  .method-grid,
  .mission-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .tool-side,
  .quote-side,
  .contact-page-side {
    grid-template-columns: minmax(0, 1fr);
  }

  .tool-form--inline {
    grid-template-columns: minmax(0, 1fr);
  }

  .tool-form--inline .btn {
    width: 100%;
  }

  .form-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .field--full {
    grid-column: auto;
  }

  .form-foot {
    flex-direction: column;
    align-items: stretch;
  }

  .form-foot .btn {
    width: 100%;
  }

  .branch-card__badge {
    position: static;
    align-self: flex-start;
    margin-bottom: 0.15rem;
  }

  .quote-promise {
    gap: 0.4rem;
  }

  .footer-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .footer-grid .footer-col:first-child {
    grid-column: auto;
  }

  .newsletter__row {
    flex-direction: column;
  }

  .newsletter .btn {
    width: 100%;
  }

  .brand--lg .brand__name {
    font-size: 1.18rem;
  }

  .brand--lg .brand__mark {
    width: 52px;
    height: 52px;
  }

  .site-header.is-scrolled .brand__sub {
    display: none;
  }

  .cookie-note {
    inset-inline: 0.65rem;
    bottom: 0.65rem;
    padding: 0.9rem;
  }

  .toast-region {
    inset-inline: 0.65rem;
    bottom: 0.65rem;
    width: auto;
  }
}

@media (max-width: 560px) {
  :root {
    --header-h: 76px;
