const fs = require("fs");
const path = require("path");
const root = "D:/OpenCode";
const files = [];
function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (!["node_modules", ".git", "assets", "tools"].includes(e.name)) walk(p);
    } else if (e.name.endsWith(".html")) files.push(p);
  }
}
walk(root);

let problems = 0;
const idsByFile = {};
for (const f of files) {
  const rel = path.relative(root, f).replace(/\\/g, "/");
  const html = fs.readFileSync(f, "utf8");
  const ids = [...html.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1]);
  const seen = new Set();
  for (const id of ids) {
    if (seen.has(id)) {
      console.log("DUP ID", rel, id);
      problems++;
    }
    seen.add(id);
  }
  idsByFile[rel] = seen;

  for (const m of html.matchAll(/<img\b[^>]*>/g)) {
    if (!/\balt=/.test(m[0])) {
      console.log("IMG NO ALT", rel, m[0].slice(0, 80));
      problems++;
    }
  }
  for (const m of html.matchAll(/href="([^"]+)"/g)) {
    const href = m[1];
    if (/^(https?:|mailto:|tel:|#|javascript:)/.test(href)) continue;
    const [p] = href.split("#");
    if (!p) continue;
    const target = path.resolve(path.dirname(f), decodeURIComponent(p));
    if (!fs.existsSync(target)) {
      console.log("BROKEN LINK", rel, href);
      problems++;
    }
  }
}

// anchor targets
for (const f of files) {
  const rel = path.relative(root, f).replace(/\\/g, "/");
  const html = fs.readFileSync(f, "utf8");
  for (const m of html.matchAll(/href="([^"]*#[^"]+)"/g)) {
    const href = m[1];
    if (/^https?:/.test(href)) continue;
    const [p, hash] = href.split("#");
    const targetFile = p ? path.resolve(path.dirname(f), decodeURIComponent(p)) : f;
    const targetRel = path.relative(root, targetFile).replace(/\\/g, "/");
    if (!idsByFile[targetRel]) continue;
    if (!idsByFile[targetRel].has(hash)) {
      console.log("MISSING ANCHOR", rel, href);
      problems++;
    }
  }
}

console.log("Files:", files.length, "| Problems:", problems);

