[
  "tools.browser.back — tools.browser.back({
  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
}): Promise<{
  /** @pattern ^tab_[a-f0-9-]{36}$ */
  id: string,
  /** @maxLength 16384 */
  url: string,
  /** @maxLength 2048 */
  title: string,
  loading: boolean,
  /** @maxLength 2048 */
  loadError?: string,
  canGoBack: boolean,
  canGoForward: boolean,
  /** @integer @minimum 0 */
  generation: number,
}>",
  "tools.browser.check — tools.browser.check({
  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
  /**
   * Element ref from this tab's latest snapshot or a user's browser comment. Never invent or reuse refs across tabs.
   * @pattern ^@?e[1-9][0-9]*$
   */
  ref: string,
  checked: boolean,
}): Promise<{
  /** @pattern ^tab_[a-f0-9-]{36}$ */
  id: string,
  /** @maxLength 16384 */
  url: string,
  /** @maxLength 2048 */
  title: string,
  loading: boolean,
  /** @maxLength 2048 */
  loadError?: string,
  canGoBack: boolean,
  canGoForward: boolean,
  /** @integer @minimum 0 */
  generation: number,
}>",
  "tools.browser.click — tools.browser.click({
  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
  /**
   * Element ref from this tab's latest snapshot or a user's browser comment. Never invent or reuse refs across tabs.
   * @pattern ^@?e[1-9][0-9]*$
   */
  ref: string,
  button?: "left" | "right" | "middle",
  count?: 1 | 2,
