const tabID = "tab_a8114389-e035-4579-91e3-c05ec880a0d7";
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const widths = [1440, 1280, 1180, 1100, 1024, 900, 720, 560, 390, 320];
    const out = [];
    for (const w of widths) {
      const frame = document.createElement('iframe');
      frame.style.cssText = 'position:fixed;top:0;left:-10000px;width:' + w + 'px;height:900px;border:0';
      frame.src = 'index.html';
      document.body.appendChild(frame);
      await new Promise((resolve) => frame.addEventListener('load', resolve, { once: true }));
      await new Promise((r) => setTimeout(r, 120));
      const d = frame.contentDocument;
      const win = frame.contentWindow;
      const pick = (sel) => d.querySelector(sel);
      const cols = (sel) => {
        const el = pick(sel);
        return el ? win.getComputedStyle(el).gridTemplateColumns : null;
      };
      const headerInner = pick('.header-bar__inner');
      const nav = pick('.nav');
      const toggle = pick('.nav-toggle');
      out.push({
        width: w,
        scrollWidth: d.documentElement.scrollWidth,
        overflow: d.documentElement.scrollWidth - w,
        headerH: headerInner ? Math.round(headerInner.getBoundingClientRect().height) : null,
        brandW: Math.round(pick('.brand--lg').getBoundingClientRect().width),
        navDisplay: nav ? win.getComputedStyle(nav).display : null,
        toggleDisplay: toggle ? win.getComputedStyle(toggle).display : null,
        topbarDisplay: pick('.topbar') ? win.getComputedStyle(pick('.topbar')).display : null,
        tools: cols('.tool-grid'),
        countries: cols('.country-grid'),
        values: cols('.values-grid'),
        valuesCards: cols('.values-cards'),
        vip: cols('.vip-band'),
        promo: cols('.promo-grid'),
        footer: cols('.footer-grid'),
        contact: cols('.contact-page-grid')
      });
      frame.remove();
    }
    return out;
  })()`
});
return res.value;

