const tabID = "tab_a8114389-e035-4579-91e3-c05ec880a0d7";
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const frame = document.createElement('iframe');
    frame.style.cssText = 'position:fixed;top:0;left:-10000px;width:1440px;height:1000px;border:0';
    frame.src = 'index.html';
    document.body.appendChild(frame);
    await new Promise((r) => frame.addEventListener('load', r, { once: true }));
    await new Promise((r) => setTimeout(r, 200));
    const d = frame.contentDocument;
    const win = frame.contentWindow;
    const info = (sel) => {
      const el = d.querySelector(sel);
      if (!el) return null;
      const r = el.getBoundingClientRect();
      const cs = win.getComputedStyle(el);
      return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), fs: cs.fontSize, ff: cs.fontFamily.split(',')[0], dir: cs.direction };
    };
    const out = {
      topbar: info('.topbar'),
      topbarPhone: info('.topbar__item--phone'),
      brand: info('.brand--lg'),
      brandName: info('.brand--lg .brand__name'),
      brandSub: info('.brand--lg .brand__sub'),
      brandMark: info('.brand--lg .brand__mark'),
      nav: info('.nav'),
      navFirst: info('.nav__item'),
      navLast: info('.nav__item:last-child'),
      actions: info('.header-actions'),
      quoteBtn: info('.header-actions .btn'),
      valuesGrid: info('.values-grid'),
      valuesCards: info('.values-cards'),
      valuesList: info('.values-list'),
      firstValueCard: info('.value-card'),
      listTitle: info('.values-list__title'),
      tools: info('.tool-grid'),
      firstTool: info('.tool-card'),
      vip: info('.vip-band'),
      promo: info('.promo-grid'),
      footer: info('.site-footer'),
      hero: info('.hero'),
      h1: info('.hero__title, h1'),
      cookie: info('#cookieNote')
    };
    frame.remove();
    return out;
  })()`
});
return res.value;

