const tabID = "tab_a8114389-e035-4579-91e3-c05ec880a0d7";
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const frame = document.createElement('iframe');
    frame.style.cssText = 'position:fixed;top:0;left:0;width:1440px;height:900px;border:0;z-index:9999;background:#fff';
    frame.src = 'index.html';
    document.body.appendChild(frame);
    await new Promise((r) => frame.addEventListener('load', r, { once: true }));
    await new Promise((r) => setTimeout(r, 250));
    const d = frame.contentDocument;
    const win = frame.contentWindow;
    const out = {};
    const items = [...d.querySelectorAll('.has-dropdown')];
    out.dropdownCount = items.length;
    out.toggles = items.map((i) => {
      const t = i.querySelector('.nav__toggle');
      return { text: t.textContent.trim().replace(/\\s+/g, ' '), expanded: t.getAttribute('aria-expanded'), panelId: t.getAttribute('aria-controls') || null };
    });
    const first = items[0];
    const toggle = first.querySelector('.nav__toggle');
    const panel = first.querySelector('.nav__dropdown');
    toggle.dispatchEvent(new win.MouseEvent('click', { bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 150));
    const cs = win.getComputedStyle(panel);
    const pr = panel.getBoundingClientRect();
    out.afterClick = {
      open: first.classList.contains('is-open'),
      expanded: toggle.getAttribute('aria-expanded'),
      opacity: cs.opacity,
      visibility: cs.visibility,
      pointerEvents: cs.pointerEvents,
      panelBox: { x: Math.round(pr.x), y: Math.round(pr.y), w: Math.round(pr.width), h: Math.round(pr.height) },
      panelOverflowRight: Math.round(pr.right - win.innerWidth),
      panelOverflowLeft: Math.round(0 - pr.left)
    };
    toggle.dispatchEvent(new win.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await new Promise((r) => setTimeout(r, 100));
    out.afterEscape = { open: first.classList.contains('is-open'), expanded: toggle.getAttribute('aria-expanded'), focused: d.activeElement === toggle };
    // second dropdown closes the first
    toggle.dispatchEvent(new win.MouseEvent('click', { bubbles: true, cancelable: true }));
    const secondToggle = items[1].querySelector('.nav__toggle');
    secondToggle.dispatchEvent(new win.MouseEvent('click', { bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 100));
    out.mutualExclusive = { first: first.classList.contains('is-open'), second: items[1].classList.contains('is-open') };
    d.body.dispatchEvent(new win.MouseEvent('click', { bubbles: true }));
    await new Promise((r) => setTimeout(r, 100));
    out.outsideClickCloses = !items[1].classList.contains('is-open');
    out.navLabels = [...d.querySelectorAll('.nav > .nav__list > .nav__item')].map((i) => i.textContent.trim().replace(/\\s+/g, ' '));
    frame.remove();
    return out;
  })()`
});
return res.value;

