const tabID = "tab_a8114389-e035-4579-91e3-c05ec880a0d7";
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    async function openFrame(src, w, h) {
      const frame = document.createElement('iframe');
      frame.style.cssText = 'position:fixed;top:0;left:0;width:' + w + 'px;height:' + (h || 900) + 'px;border:0;z-index:9999;background:#fff';
      frame.src = src;
      document.body.appendChild(frame);
      await new Promise((r) => frame.addEventListener('load', r, { once: true }));
      await wait(200);
      return frame;
    }
    const out = {};

    // ---- Mobile menu at 390 ----
    let frame = await openFrame('index.html', 390, 800);
    let d = frame.contentDocument, win = frame.contentWindow;
    const toggle = d.querySelector('.nav-toggle');
    const menu = d.querySelector('#mobileMenu');
    out.menuBefore = { open: menu.classList.contains('is-open'), ariaHidden: menu.getAttribute('aria-hidden'), expanded: toggle.getAttribute('aria-expanded') };
    toggle.click();
    await wait(200);
    out.menuAfter = {
      open: menu.classList.contains('is-open'),
      ariaHidden: menu.getAttribute('aria-hidden'),
      expanded: toggle.getAttribute('aria-expanded'),
      bodyLocked: d.body.classList.contains('is-locked'),
      focusedInMenu: menu.contains(d.activeElement),
      scrollH: menu.scrollHeight, viewH: menu.clientHeight,
      menuOverflow: menu.scrollHeight - menu.clientHeight,
      linkCount: menu.querySelectorAll('a').length
    };
    win.dispatchEvent(new win.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await wait(150);
    out.menuEscape = { open: menu.classList.contains('is-open'), expanded: toggle.getAttribute('aria-expanded'), focusOnToggle: d.activeElement === toggle, bodyLocked: d.body.classList.contains('is-locked') };
    out.mobileOverflow = d.documentElement.scrollWidth - 390;
    frame.remove();

    // ---- Newsletter on homepage ----
    frame = await openFrame('index.html', 1200, 900);
    d = frame.contentDocument; win = frame.contentWindow;
    let opened = null;
    win.open = function (url) { opened = url; return {}; };
    const newsForm = d.querySelector('form[data-newsletter]');
    const emailField = newsForm.elements['email'];
    emailField.value = 'test@example.com';
    newsForm.dispatchEvent(new win.Event('submit', { bubbles: true, cancelable: true }));
    await wait(150);
    out.newsletter = {
      status: d.querySelector('.footer-news .form-status')?.textContent || d.querySelector('form[data-newsletter] .form-status')?.textContent,
      stored: win.localStorage.getItem('khatruk_newsletter'),
      openedWhatsApp: opened ? opened.slice(0, 40) : null,
      toast: d.querySelector('#toastRegion .toast')?.textContent?.trim()
    };
    // invalid email
    emailField.value = 'not-an-email';
    newsForm.dispatchEvent(new win.Event('submit', { bubbles: true, cancelable: true }));
    await wait(100);
    out.newsletterInvalid = { status: newsForm.querySelector('.form-status')?.textContent };
    // ---- Cookie accept ----
    const cookie = d.querySelector('#cookieNote');
    out.cookieBefore = { hidden: cookie.hasAttribute('hidden') };
    const acc = cookie.querySelector('[data-cookie-accept]');
    acc.click();
    await wait(400);
    out.cookieAfter = { hidden: cookie.hasAttribute('hidden'), stored: win.localStorage.getItem('khatruk_cookie_consent'), toast: d.querySelector('#toastRegion .toast:last-child')?.textContent?.trim() };
    frame.remove();

    // ---- Tracking ----
    frame = await openFrame('pages/tracking.html', 1200, 1000);
    d = frame.contentDocument; win = frame.contentWindow;
    const tForm = d.querySelector('[data-tracking]');
    tForm.elements['passport'].value = '01234567';
    tForm.elements['transaction'].value = 'KHT-2026-00123';
    tForm.dispatchEvent(new win.Event('submit', { bubbles: true, cancelable: true }));
    await wait(200);
    const tRes = d.querySelector('[data-tracking-result]');
    out.tracking = {
      hidden: tRes.hasAttribute('hidden'),
      text: tRes.textContent.replace(/\\s+/g, ' ').trim().slice(0, 300),
      waHref: tRes.querySelector('a[href*="wa.me"]')?.getAttribute('href')?.slice(0, 90),
      hasMasked: tRes.innerHTML.includes('01••••67')
    };
    // passport too short
    tForm.elements['passport'].value = '12';
    tForm.dispatchEvent(new win.Event('submit', { bubbles: true, cancelable: true }));
    await wait(120);
    out.trackingShortToast = d.querySelector('#toastRegion .toast:last-child')?.textContent?.trim();
    frame.remove();

    // ---- Visa check ----
    frame = await openFrame('pages/visa-check.html', 1200, 1000);
    d = frame.contentDocument; win = frame.contentWindow;
    const vForm = d.querySelector('[data-visa-check]');
    vForm.elements['nationality'].value = 'YE';
    vForm.elements['destination'].value = 'TR';
    vForm.elements['purpose'].value = 'سياحة';
    vForm.dispatchEvent(new win.Event('submit', { bubbles: true, cancelable: true }));
    await wait(250);
    const vRes = d.querySelector('[data-visa-result]');
    out.visa = {
      hidden: vRes.hasAttribute('hidden'),
      text: vRes.textContent.replace(/\\s+/g, ' ').trim().slice(0, 260),
      waHref: vRes.querySelector('a[href*="wa.me"]')?.getAttribute('href')?.slice(0, 80)
    };
    // Umrah special case
    vForm.elements['destination'].value = 'SA';
    vForm.elements['purpose'].value = 'عمرة وزيارة';
    vForm.dispatchEvent(new win.Event('submit', { bubbles: true, cancelable: true }));
    await wait(200);
    out.visaUmrah = vRes.textContent.replace(/\\s+/g, ' ').trim().slice(0, 160);
    frame.remove();

    // ---- Country explorer ----
    frame = await openFrame('pages/discover-countries.html', 1200, 1000);
    d = frame.contentDocument; win = frame.contentWindow;
    const eForm = d.querySelector('[data-country-explorer]');
    eForm.elements['nationality'].value = 'GB';
    eForm.dispatchEvent(new win.Event('submit', { bubbles: true, cancelable: true }));
    await wait(300);
    const grid = d.querySelector('[data-country-results]');
    out.explore = {
      count: grid.children.length,
      summary: d.querySelector('[data-explore-summary]')?.textContent.replace(/\\s+/g, ' ').trim().slice(0, 160),
      first: grid.firstElementChild?.textContent.replace(/\\s+/g, ' ').trim().slice(0, 120),
      hiddenSummary: d.querySelector('[data-explore-summary]')?.hasAttribute('hidden')
    };
    frame.remove();

    return out;
  })()`
});
return res.value;

