const tabID = "tab_a8114389-e035-4579-91e3-c05ec880a0d7";
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    async function openFrame(src, w) {
      const frame = document.createElement('iframe');
      frame.style.cssText = 'position:fixed;top:0;left:0;width:' + w + 'px;height:900px;border:0;z-index:9999;background:#fff';
      frame.src = src;
      document.body.appendChild(frame);
      await new Promise((r) => frame.addEventListener('load', r, { once: true }));
      await wait(120);
      return frame;
    }
    const pages = ['index.html','pages/about.html','pages/contact.html','pages/quote.html','pages/tracking.html','pages/visa-check.html','pages/discover-countries.html','pages/notifications.html','pages/branches.html','pages/destinations.html','pages/refund-policy.html','pages/quality-assurance.html','pages/how-to-use.html','pages/payment-methods.html','pages/reviews.html','pages/partners.html','pages/vision-mission.html','pages/manager-message.html','pages/privacy-policy.html','pages/cookie-policy.html','services/index.html','services/transportation.html','services/vip-concierge.html','services/tour-guides.html'];
    const out = [];
    for (const p of pages) {
      const row = { page: p };
      for (const w of [1440, 390]) {
        const frame = await openFrame(p, w);
        const d = frame.contentDocument;
        const h1s = d.querySelectorAll('h1').length;
        const footer = !!d.querySelector('.site-footer');
        const cookie = !!d.querySelector('#cookieNote');
        const toast = !!d.querySelector('#toastRegion');
        const clock = !!d.querySelector('[data-clock-greg]');
        const nav = !!d.querySelector('.nav');
        const menu = !!d.querySelector('#mobileMenu');
        const over = d.documentElement.scrollWidth - w;
        const broken = [...d.querySelectorAll('img')].filter((img) => img.complete && img.naturalWidth === 0).map((img) => img.getAttribute('src'));
        if (w === 1440) Object.assign(row, { h1s, footer, cookie, toast, clock, nav, menu });
        row['over' + w] = over;
        if (broken.length) row['broken' + w] = broken;
        frame.remove();
      }
      out.push(row);
    }
    return out;
  })()`
});
return res.value;

