    const visaChip = chips.find((c) => c.getAttribute('data-filter') === 'visa');
    visaChip.click();
    await wait(150);
    out.visaFilter = {
      pressed: chips.filter((c) => c.getAttribute('aria-pressed') === 'true').map((c) => c.getAttribute('data-filter')),
