      hiddenCount: [...d.querySelectorAll('[data-category]')].filter((c) => c.classList.contains('is-hidden')).length
    };
    const allChip = chips.find((c) => c.getAttribute('data-filter') === 'all');
    allChip.click();
    await wait(100);
    out.allFilter = { hiddenCount: [...d.querySelectorAll('[data-category]')].filter((c) => c.classList.contains('is-hidden')).length };
    // notification topbar with granted stub
    win.Notification = { permission: 'granted' };
    d.querySelector('.topbar__notify').click();
    await wait(150);
    out.notifyGranted = { statuses: [...d.querySelectorAll('[data-notify-status]')].map((n) => n.textContent.trim()), toast: d.querySelector('#toastRegion .toast')?.textContent.trim() };
    frame.remove();
    return out;
  })()`
});
return res.value;

