    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    const out = [];
    for (const w of [1440, 1280, 1241, 1240, 1180, 1101, 1100]) {
      const frame = document.createElement('iframe');
      frame.style.cssText = 'position:fixed;top:0;left:-10000px;width:' + w + 'px;height:900px;border:0';
      frame.src = 'index.html';
      document.body.appendChild(frame);
      await new Promise((r) => frame.addEventListener('load', r, { once: true }));
      await wait(140);
      const d = frame.contentDocument, win = frame.contentWindow;
      const b = (sel) => { const el = d.querySelector(sel); if (!el) return null; const r = el.getBoundingClientRect(); return { x: Math.round(r.x), right: Math.round(r.right), w: Math.round(r.width) }; };
      const tb = d.querySelector('.topbar__inner');
      const brand = b('.brand--lg');
      const nav = b('.nav');
      const actions = b('.header-actions');
      const gapBrandNav = brand && nav ? (brand.x - nav.right) : null;
      const topbarOverflow = tb ? tb.scrollWidth - tb.clientWidth : null;
      out.push({
        width: w,
        scrollWidth: d.documentElement.scrollWidth,
        topbarOverflow,
        brand, nav, actions,
        gapBrandNav,
        navDisplay: nav ? win.getComputedStyle(d.querySelector('.nav')).display : null,
        phoneDisplay: win.getComputedStyle(d.querySelector('.topbar__item--phone')).display,
        emailDisplay: win.getComputedStyle(d.querySelector('.topbar__group a[href^="mailto"]')).display
      });
      frame.remove();
    }
    return out;
  })()`
});
return res.value;

