const tabID = "tab_a8114389-e035-4579-91e3-c05ec880a0d7";
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    const frame = document.createElement('iframe');
    frame.style.cssText = 'position:fixed;top:0;left:0;width:1200px;height:800px;border:0;z-index:9999;background:#fff';
    frame.src = 'index.html';
    document.body.appendChild(frame);
    await new Promise((r) => frame.addEventListener('load', r, { once: true }));
    await wait(250);
    const d = frame.contentDocument, win = frame.contentWindow;
    const link = d.querySelector('a[href="#contact"]');
    link.click();
    await wait(900);
    const section = d.querySelector('#contact');
    const header = d.querySelector('#siteHeader');
    const sr = section.getBoundingClientRect();
    const hr = header.getBoundingClientRect();
    const out = {
      scrollY: Math.round(win.scrollY),
      sectionTop: Math.round(sr.top),
      headerBottom: Math.round(hr.bottom),
      gap: Math.round(sr.top - hr.bottom),
      headerScrolled: header.classList.contains('is-scrolled'),
      topbarMaxHeight: win.getComputedStyle(d.querySelector('.topbar')).maxHeight,
      headerHeight: Math.round(hr.height),
      hash: win.location.hash,
      contactExists: !!section
    };
    // skip link focus
    win.scrollTo(0, 0);
    await wait(300);
    d.querySelector('.skip-link').focus();
    out.skipLink = { visible: d.activeElement === d.querySelector('.skip-link'), text: d.querySelector('.skip-link').textContent.trim() };
    frame.remove();
    return out;
  })()`
});
return res.value;

