const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    const out = [];
    for (const p of ['pages/tracking.html','pages/about.html','services/transportation.html','services/index.html']) {
      const frame = document.createElement('iframe');
      frame.style.cssText = 'position:fixed;top:0;left:-10000px;width:1280px;height:900px;border:0';
      frame.src = p;
      document.body.appendChild(frame);
      await new Promise((r) => frame.addEventListener('load', r, { once: true }));
      await wait(140);
      const d = frame.contentDocument, win = frame.contentWindow;
      const crumb = d.querySelector('.breadcrumb');
      const h1 = d.querySelector('h1');
      const header = d.querySelector('#siteHeader');
      const cr = crumb?.getBoundingClientRect();
      const hr = header.getBoundingClientRect();
      out.push({ page: p, crumbTop: cr ? Math.round(cr.top) : null, headerBottom: Math.round(hr.bottom), h1Top: h1 ? Math.round(h1.getBoundingClientRect().top) : null, crumbVisible: cr ? cr.top >= hr.bottom : null });
      frame.remove();
    }
    return out;
  })()`
});
return res.value;

