:root {
  --header-h: 104px;
}

.site-header .header-bar__inner {
  height: var(--header-h);
}

.site-header.is-scrolled .header-bar__inner {
  height: 80px;
}

.brand__name,
.brand--lg .brand__name {
  font-family: var(--font-display);
  letter-spacing: 0;
  color: var(--gold);
}

.brand--footer .brand__name {
  color: var(--gold);
}

.mobile-menu__head .brand__name {
  color: var(--gold);
}

.brand__sub,
.brand--lg .brand__sub {
  color: rgba(201, 162, 75, 0.86);
  letter-spacing: 0.02em;
}

.site-header.is-scrolled .brand--lg .brand__name {
  color: #8a6a2a;
}

.site-header.is-scrolled .brand__sub {
  color: #8a6a2a;
}

.brand--lg .brand__mark {
  width: 84px;
  height: 84px;
  transition: width 0.35s var(--ease-soft), height 0.35s var(--ease-soft);
}

.site-header.is-scrolled .brand--lg .brand__mark {
  width: 62px;
  height: 62px;
}

.brand--lg .brand__name {
  font-size: clamp(1.68rem, 1.95vw, 1.98rem);
  line-height: 1.15;
}

.brand--lg .brand__sub {
  font-size: 0.82rem;
  font-weight: 600;
}

.brand--footer .brand__mark {
  width: 68px;
  height: 68px;
}

.mobile-menu__head .brand__mark {
  width: 64px;
  height: 64px;
}

/* Keep every phone number on a single, unspaced line */
.topbar__item--phone span,
.header-phone span,
.quick-card__phone span,
.footer-contact__row--phone span,
.channel__value--ltr,
.aside-phone span,
.meta-row__value,
.branch-card__rows a span {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  direction: ltr;
  unicode-bidi: isolate;
}

.footer-contact__row--map {
  text-decoration: none;
}

.footer-contact__row--map:hover span {
  color: var(--gold-soft);
  text-decoration: underline;
}

/* ---------- Language switcher ---------- */
.lang-switch {
  position: relative;
}

.lang-switch__btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  height: 40px;
  padding: 0 0.72rem;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 999px;
  background: transparent;
  color: var(--hdr-fg);
  font-family: var(--font-body);
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  transition: border-color 0.25s var(--ease-soft), color 0.25s var(--ease-soft),
    background-color 0.25s var(--ease-soft);
}

.lang-switch__btn:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.lang-switch__globe {
  width: 16px;
  height: 16px;
  color: var(--gold);
  flex: 0 0 auto;
}

.lang-switch__chev {
  width: 13px;
  height: 13px;
  opacity: 0.65;
  flex: 0 0 auto;
  transition: transform 0.28s var(--ease-soft);
}

.lang-switch__btn[aria-expanded="true"] .lang-switch__chev {
  transform: rotate(180deg);
}

.lang-switch__btn[aria-expanded="true"] {
  border-color: var(--gold);
  color: var(--gold);
}

.site-header.is-scrolled .lang-switch__btn {
  border-color: var(--line-strong);
}

.lang-switch__menu {
  position: absolute;
  top: calc(100% + 14px);
  inset-inline-end: 0;
  z-index: 140;
  width: min(342px, calc(100vw - 28px));
  max-height: calc(100vh - 130px);
  overflow-y: auto;
  padding: 0.9rem;
  border: 1px solid rgba(46, 39, 102, 0.1);
  border-radius: 18px;
  background: #fff;
  color: var(--ink);
  box-shadow: 0 32px 64px -32px rgba(20, 16, 50, 0.55);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: opacity 0.24s var(--ease-soft), transform 0.24s var(--ease-soft),
    visibility 0.24s var(--ease-soft);
}

.lang-switch.is-open .lang-switch__menu {
  opacity: 1;
  visibility: visible;
  transform: none;
}

.lang-switch__title {
  display: block;
  margin-bottom: 0.55rem;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.lang-switch__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.25rem;
}

.lang-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  padding: 0.52rem 0.62rem;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 0.8rem;
  font-weight: 600;
  text-align: start;
  cursor: pointer;
  transition: background-color 0.2s var(--ease-soft), color 0.2s var(--ease-soft);
}

.lang-option:hover {
  background: var(--paper-soft, #f6f7fc);
  color: var(--deep);
}

.lang-option[aria-checked="true"] {
  background: rgba(201, 162, 75, 0.16);
  color: #7a5d22;
  font-weight: 800;
}

.lang-option[aria-checked="true"]::after {
  content: "✓";
  font-size: 0.78rem;
  line-height: 1;
  color: #8a6a2a;
}

.lang-option:focus-visible,
.lang-switch__btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

/* ---------- Hero video ---------- */
.hero__video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  opacity: 0;
  filter: saturate(0.9) contrast(1.04) brightness(0.9);
  transform: scale(1.04);
  transition: opacity 1.2s var(--ease-soft);
  pointer-events: none;
}

.hero__video.is-ready {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .hero__video {
    display: none !important;
  }
}

@media (max-width: 1100px) {
  :root {
    --header-h: 94px;
  }

  .site-header.is-scrolled .header-bar__inner {
    height: 72px;
  }

  .brand--lg .brand__mark {
    width: 74px;
    height: 74px;
  }

  .site-header.is-scrolled .brand--lg .brand__mark {
    width: 58px;
    height: 58px;
  }

  .brand--lg .brand__name {
    font-size: 1.62rem;
  }
}

@media (max-width: 720px) {
  .brand--lg .brand__name {
    font-size: 1.4rem;
  }
}

@media (max-width: 560px) {
  :root {
    --header-h: 84px;
  }

  .site-header.is-scrolled .header-bar__inner {
    height: 70px;
  }

  .brand--lg .brand__mark {
    width: 62px;
    height: 62px;
  }

  .site-header.is-scrolled .brand--lg .brand__mark {
    width: 54px;
    height: 54px;
  }

  .brand--lg .brand__name {
    font-size: 1.28rem;
  }

  .lang-switch__btn {
    height: 38px;
    padding: 0 0.55rem;
  }
}

@media (max-width: 400px) {
  .lang-switch__label,
  .lang-switch__chev {
    display: none;
  }

  .lang-switch__btn {
    width: 38px;
    padding: 0;
    justify-content: center;
  }
}

